3::root{
20:.panel{position:fixed;background:var(--panel);border:1px solid var(--panel-line);border-radius:6px;
22:.brand{top:calc(14px + env(safe-area-inset-top,0px));inset-inline-start:calc(14px + env(safe-area-inset-left,0px));
32:.brand-top{display:flex;align-items:center;justify-content:space-between;gap:10px;}
37:@media (hover:hover){.lang select:hover{background:rgba(230,189,106,.12);}}
62:@media (hover:hover){button:hover{background:rgba(230,189,106,.12);}}
68:#btnMusic,#btnVoice{display:inline-flex;align-items:center;gap:7px;flex:0 0 auto;}
69:#btnVoice svg{width:14px;height:14px;flex:0 0 auto;}
70:#btnVoice:disabled{opacity:.35;cursor:default;}
71:#btnMusic svg{width:14px;height:14px;flex:0 0 auto;}
72:#btnMusic .eq{display:none;}
73:#btnMusic[aria-pressed="true"] .eq{display:inline;}
74:#btnMusic[aria-pressed="true"] .eq rect{animation:eq 1.1s ease-in-out infinite;transform-origin:50% 100%;transform-box:fill-box;}
75:#btnMusic[aria-pressed="true"] .eq rect:nth-child(2){animation-delay:-.35s;}
76:#btnMusic[aria-pressed="true"] .eq rect:nth-child(3){animation-delay:-.7s;}
77:#btnMusic[aria-pressed="true"] .note{display:none;}
81:.views{top:calc(14px + env(safe-area-inset-top,0px));inset-inline-end:calc(14px + env(safe-area-inset-right,0px));
89:@media (hover:hover){.donate:hover{background:rgba(230,189,106,.1);}}
96:.views{max-height:calc(100vh - 28px - 26px - env(safe-area-inset-top,0px) - env(safe-area-inset-bottom,0px));overflow-y:auto;}   /* 28 = hai lề 14 px; 26 = padding 12 px × 2 + viền 1 px × 2 (max-height tính phần nội dung) */
107:.wx-impact{display:flex;flex-direction:column;gap:6px;max-height:max(120px,calc(100vh - 560px));overflow-y:auto;}   /* chừa chỗ cho bảng Thông số ở góc dưới */
