content.content:
1	/* Bố cục: khung 3D toàn màn hình, các bảng điều khiển nổi kiểu "bảng đồng" ở bốn góc.
2	   Giao diện cố ý chỉ một tông tối để nổi trên cảnh 3D. */
3	:root{
4	  --ink:#0b1216;            /* nền trang */
5	  --panel:rgba(10,18,22,.78);
6	  --panel-line:rgba(226,186,104,.26);
7	  --gold:#e6bd6a;           /* vàng kim của thân rồng */
8	  --gold-deep:#a97a28;
9	  --text:#eef0ea;
10	  --muted:#9fb0ad;
11	  --han:#5aa89a;            /* xanh sông Hàn */
12	  --font-display:'Cormorant Garamond','Times New Roman',serif;
13	  --font-body:'Be Vietnam Pro',system-ui,-apple-system,'Segoe UI',sans-serif;
14	  --font-mono:'JetBrains Mono',ui-monospace,Menlo,Consolas,monospace;
15	  color-scheme:dark;
16	}
17	[hidden]{display:none!important;}
18	html,body{height:100%;margin:0;overflow:hidden;background:var(--ink);color:var(--text);font-family:var(--font-body);}
19	#scene{position:fixed;inset:0;width:100%;height:100%;height:100dvh;display:block;outline:none;touch-action:none;}
20	.panel{position:fixed;background:var(--panel);border:1px solid var(--panel-line);border-radius:6px;
21	  backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);box-shadow:0 10px 30px rgba(0,0,0,.35);}
22	.brand{top:calc(14px + env(safe-area-inset-top,0px));inset-inline-start:calc(14px + env(safe-area-inset-left,0px));
23	  padding:14px 16px 14px;max-width:min(360px,calc(100vw - 28px));display:flex;flex-direction:column;gap:10px;}
24	.eyebrow{font-family:var(--font-mono);font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--han);}
25	h1{margin:0;font-family:var(--font-display);font-weight:600;font-size:34px;line-height:1;color:var(--gold);letter-spacing:.01em;text-wrap:balance;}
26	h1 span{color:var(--text);font-weight:500;font-size:.62em;letter-spacing:.04em;}
27	h1 .h1-main{color:var(--gold);font-weight:600;font-size:1em;letter-spacing:inherit;}
28	.row{display:flex;flex-wrap:wrap;gap:6px;}
29	.weather-row{display:flex;flex-direction:column;gap:6px;}
30	.weather-row .mini-select{margin-top:0;}
31	.weather-row output,#weatherKVal{min-width:3.2em;text-align:end;font-family:var(--font-mono);}
32	.brand-top{display:flex;align-items:center;justify-content:space-between;gap:10px;}
33	.lang{position:relative;flex:0 0 auto;}
34	.lang select{appearance:none;-webkit-appearance:none;font:500 11.5px/1.2 var(--font-body);color:var(--text);
35	  background:rgba(255,255,255,.04);border:1px solid rgba(230,189,106,.32);border-radius:4px;
36	  padding-block:5px;padding-inline:8px 22px;cursor:pointer;max-width:132px;}
37	@media (hover:hover){.lang select:hover{background:rgba(230,189,106,.12);}}
38	.lang select:focus-visible{outline:2px solid var(--gold);outline-offset:2px;}
39	.lang select option{background:var(--ink);color:var(--text);}
40	.lang::after{content:"";position:absolute;inset-inline-end:8px;top:50%;width:6px;height:6px;margin-top:-5px;
41	  border-right:1.5px solid var(--gold);border-bottom:1.5px solid var(--gold);transform:rotate(45deg);pointer-events:none;}
42	/* Font và nhịp chữ theo từng hệ chữ viết */
43	html[lang=ko]{--font-display:'Noto Serif KR',serif;--font-body:'Noto Sans KR',system-ui,sans-serif;--font-mono:'JetBrains Mono','Noto Sans KR',monospace;}
44	html[lang=ja]{--font-display:'Noto Serif JP',serif;--font-body:'Noto Sans JP',system-ui,sans-serif;--font-mono:'JetBrains Mono','Noto Sans JP',monospace;}
45	html[lang=zh]{--font-display:'Noto Serif SC',serif;--font-body:'Noto Sans SC',system-ui,sans-serif;--font-mono:'JetBrains Mono','Noto Sans SC',monospace;}
46	html[lang=th]{--font-display:'Noto Serif Thai',serif;--font-body:'Noto Sans Thai',system-ui,sans-serif;--font-mono:'JetBrains Mono','Noto Sans Thai',monospace;}
47	html[lang=ar]{--font-display:'Noto Naskh Arabic',serif;--font-body:'Noto Sans Arabic',system-ui,sans-serif;--font-mono:'JetBrains Mono','Noto Sans Arabic',monospace;}
48	html[lang=hi]{--font-display:'Noto Serif Devanagari',serif;--font-body:'Noto Sans Devanagari',system-ui,sans-serif;--font-mono:'JetBrains Mono','Noto Sans Devanagari',monospace;}
49	html[lang=ru]{--font-display:'Noto Serif',serif;--font-body:'Noto Sans',system-ui,sans-serif;--font-mono:'JetBrains Mono','Noto Sans',monospace;}
50	html:is([lang=ko],[lang=ja],[lang=zh],[lang=th],[lang=ar],[lang=hi]) h1{font-size:27px;line-height:1.3;}
51	html:is([lang=ko],[lang=ja],[lang=zh],[lang=th],[lang=ar],[lang=hi]) #tourCaption h2{font-size:20px;line-height:1.35;}
52	html:is([lang=ko],[lang=ja],[lang=zh],[lang=th],[lang=ar],[lang=hi]) .specs dd{font-size:20px;}
53	html:is([lang=ko],[lang=ja],[lang=zh],[lang=th],[lang=ar],[lang=hi]) #loading{font-size:22px;}
54	html:is([lang=ko],[lang=ja],[lang=zh],[lang=th],[lang=ar],[lang=hi]) .eyebrow,
55	html:is([lang=ko],[lang=ja],[lang=zh],[lang=th],[lang=ar],[lang=hi]) .label,
56	html:is([lang=ko],[lang=ja],[lang=zh],[lang=th],[lang=ar],[lang=hi]) #tourCaption .step{letter-spacing:.04em;}
57	html[lang=ar] *{letter-spacing:0!important;}
58	html:is([lang=th],[lang=hi],[lang=ar]) #tourCaption p{line-height:1.7;}
59	button{font:500 12.5px/1.2 var(--font-body);color:var(--text);background:rgba(255,255,255,.04);
60	  border:1px solid rgba(230,189,106,.32);border-radius:4px;padding:8px 11px;cursor:pointer;
61	  transition:background .15s,border-color .15s,color .15s;}
62	@media (hover:hover){button:hover{background:rgba(230,189,106,.12);}}
63	button:focus-visible,input:focus-visible{outline:2px solid var(--gold);outline-offset:2px;}
64	button[aria-pressed="true"]{background:linear-gradient(180deg,var(--gold),var(--gold-deep));color:#1a1206;border-color:var(--gold);}
65	.slider{display:flex;align-items:center;gap:8px;font-size:11.5px;color:var(--muted);}
66	.slider input{flex:1;accent-color:var(--gold);min-width:0;}
67	.audio-row{display:flex;align-items:center;gap:10px;}
68	#btnMusic,#btnVoice{display:inline-flex;align-items:center;gap:7px;flex:0 0 auto;}
69	#btnVoice svg{width:14px;height:14px;flex:0 0 auto;}
70	#btnVoice:disabled{opacity:.35;cursor:default;}
71	#btnMusic svg{width:14px;height:14px;flex:0 0 auto;}
72	#btnMusic .eq{display:none;}
73	#btnMusic[aria-pressed="true"] .eq{display:inline;}
74	#btnMusic[aria-pressed="true"] .eq rect{animation:eq 1.1s ease-in-out infinite;transform-origin:50% 100%;transform-box:fill-box;}
75	#btnMusic[aria-pressed="true"] .eq rect:nth-child(2){animation-delay:-.35s;}
76	#btnMusic[aria-pressed="true"] .eq rect:nth-child(3){animation-delay:-.7s;}
77	#btnMusic[aria-pressed="true"] .note{display:none;}
78	@keyframes eq{0%,100%{transform:scaleY(.35);}50%{transform:scaleY(1);}}
79	.audio-row input{flex:1;min-width:0;accent-color:var(--gold);}
80	.audio-row input:disabled{opacity:.35;}
81	.views{top:calc(14px + env(safe-area-inset-top,0px));inset-inline-end:calc(14px + env(safe-area-inset-right,0px));
82	  padding:12px;display:flex;flex-direction:column;gap:6px;width:228px;}
83	.seg{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:3px;padding:3px;border:1px solid var(--panel-line);border-radius:5px;margin-bottom:2px;}
84	.seg button{min-width:0;padding:6px 4px;font-size:11px;line-height:1.2;text-align:center;background:transparent;border-color:transparent;color:var(--muted);overflow-wrap:anywhere;}
85	.mini-select{display:flex;flex-direction:column;gap:4px;margin-top:2px;font-size:10.5px;color:var(--muted);}
86	.donate{display:inline-flex;align-items:center;gap:6px;margin-top:6px;padding:6px 10px;border:1px solid rgba(230,189,106,.32);border-radius:4px;color:var(--gold);font:12px var(--font-body);text-decoration:none;}
87	.donate svg{width:14px;height:14px;flex:0 0 auto;}
88	.donate[hidden]{display:none;}
89	@media (hover:hover){.donate:hover{background:rgba(230,189,106,.1);}}
90	.swing-box{display:flex;flex-direction:column;gap:7px;padding:8px;border:1px dashed var(--panel-line);border-radius:5px;margin-top:2px;}
91	.swing-btn{background:linear-gradient(180deg,var(--gold),var(--gold-deep));color:#1a1206;border-color:var(--gold);font-weight:600;text-align:center!important;}
92	.swing-btn:disabled{opacity:.6;cursor:progress;}
93	.swing-state{font-size:11.5px;color:var(--muted);line-height:1.35;}
94	.swing-state b{color:var(--gold);font-weight:500;}
95	.swing-note{font-size:10px;color:var(--muted);line-height:1.4;}
96	.views{max-height:calc(100vh - 28px - 26px - env(safe-area-inset-top,0px) - env(safe-area-inset-bottom,0px));overflow-y:auto;}   /* 28 = hai lề 14 px; 26 = padding 12 px × 2 + viền 1 px × 2 (max-height tính phần nội dung) */
97	.mini-select select{appearance:auto;font:500 12px/1.2 var(--font-body);color:var(--text);background:rgba(255,255,255,.04);border:1px solid rgba(230,189,106,.32);border-radius:4px;padding:6px;}
98	.mini-select select option{background:var(--ink);color:var(--text);}
99	.seg button[aria-pressed="true"]{background:rgba(230,189,106,.16);border-color:rgba(230,189,106,.55);color:var(--gold);}
100	.view-list{display:flex;flex-direction:column;gap:6px;}
101	.tour-all{margin-bottom:6px;}
102	.view-list .toggle,.weather-row .toggle{display:flex;align-items:center;gap:8px;margin-top:2px;font-size:11.5px;color:var(--muted);background:transparent;}
103	.view-list .toggle::before,.weather-row .toggle::before{content:"";width:11px;height:11px;flex:0 0 auto;border:1.5px solid var(--gold);border-radius:2px;}
104	.view-list .toggle[aria-pressed="true"],.weather-row .toggle[aria-pressed="true"]{background:transparent;color:var(--text);border-color:rgba(230,189,106,.32);}
105	.view-list .toggle[aria-pressed="true"]::before,.weather-row .toggle[aria-pressed="true"]::before{background:var(--gold);box-shadow:inset 0 0 0 2px var(--ink);}
106	/* Thẻ "Ảnh hưởng tới cầu": mỗi công trình một ô (tên + trạng thái lưu thông, gió tại mặt cầu, hiệu ứng) */
107	.wx-impact{display:flex;flex-direction:column;gap:6px;max-height:max(120px,calc(100vh - 560px));overflow-y:auto;}   /* chừa chỗ cho bảng Thông số ở góc dưới */
108	.wx-item{display:flex;flex-direction:column;gap:2px;padding:6px 8px;border:1px solid rgba(230,189,106,.2);border-radius:4px;background:rgba(255,255,255,.03);font-size:11px;line-height:1.35;color:var(--muted);}
109	.wx-head{display:flex;justify-content:space-between;align-items:baseline;gap:8px;color:var(--text);font-weight:500;}
110	.wx-st{font:500 10px/1 var(--font-mono);padding:3px 6px;border-radius:3px;border:1px solid currentColor;white-space:nowrap;}
111	.wx-st.open{color:#7bd18b;}.wx-st.closed{color:#f07b6b;}
112	.wx-wind{font-variant-numeric:tabular-nums;color:var(--text);}
113	.wx-note{font-size:10px;color:var(--muted);line-height:1.4;}
114	.views .label,.specs .label{font-family:var(--font-mono);font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);margin-bottom:2px;}
115	.views button{text-align:start;}
116	.specs{inset-inline-start:calc(14px + env(safe-area-inset-left,0px));bottom:calc(14px + env(safe-area-inset-bottom,0px));padding:12px 16px;}
117	.specs dl{margin:0;display:grid;grid-template-columns:repeat(4,auto);gap:4px 22px;}
118	.specs dt{font-size:10.5px;color:var(--muted);}
119	.specs dd{margin:0;font-family:var(--font-display);font-size:22px;font-weight:600;color:var(--gold);font-variant-numeric:tabular-nums;}
120	.specs small{display:block;margin-top:6px;font-size:10.5px;color:var(--muted);max-width:44ch;line-height:1.4;}
121	.stats{inset-inline-end:calc(14px + env(safe-area-inset-right,0px));bottom:calc(14px + env(safe-area-inset-bottom,0px));
122	  padding:10px 14px;font-family:var(--font-mono);font-size:11.5px;line-height:1.6;color:var(--muted);min-width:180px;}
123	.stats b{color:var(--text);font-weight:500;font-variant-numeric:tabular-nums;}
124	.stats .show b{color:var(--gold);}
125	#hint,#swRideHint{position:fixed;left:50%;transform:translateX(-50%);top:calc(14px + env(safe-area-inset-top,0px));
126	  padding:8px 14px;font-size:12px;color:var(--text);}
127	#swStormNote{position:fixed;left:50%;transform:translateX(-50%);top:calc(58px + env(safe-area-inset-top,0px));
128	  max-width:min(440px,calc(100vw - 32px));padding:8px 14px;font-size:12px;line-height:1.45;color:var(--text);text-align:center;}
129	#tourCaption{position:fixed;left:50%;transform:translateX(-50%);bottom:calc(18px + env(safe-area-inset-bottom,0px));
130	  width:min(440px,calc(100vw - 32px));padding:12px 16px 13px;display:flex;flex-direction:column;gap:4px;transition:opacity .45s;}
131	#tourCaption.fade{opacity:0;}
132	body.touring .specs{display:none;}
133	@media (max-width:1100px){body.touring .stats{display:none;}}
134	#tourCaption .top{display:flex;justify-content:space-between;align-items:baseline;gap:12px;}
135	#tourCaption .step{font-family:var(--font-mono);font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--han);font-variant-numeric:tabular-nums;}
136	#tourCaption .exit{font-size:10.5px;color:var(--muted);}
137	/* Chữ hướng dẫn hai bản: chuột (mặc định) / cảm ứng (thiết bị không có hover) */
138	.hint-touch{display:none;}
139	@media (hover:none){.hint-mouse{display:none;}.hint-touch{display:inline;}[data-view="walk"],#hint{display:none!important;}}
140	#tourCaption h2{margin:0;font-family:var(--font-display);font-weight:600;font-size:24px;line-height:1.1;color:var(--gold);text-wrap:balance;}
141	#tourCaption p{margin:0;font-size:12.5px;line-height:1.5;color:var(--text);}
142	#tourCaption .bar{height:2px;background:rgba(255,255,255,.08);border-radius:2px;overflow:hidden;margin-top:4px;}
143	#tourCaption .bar i{display:block;height:100%;width:100%;transform:scaleX(0);transform-origin:left;background:var(--gold);}
144	[dir=rtl] #tourCaption .bar i{transform-origin:right;}
145	/* Khung chú thích Kịch bản bão: cùng kiểu #tourCaption, đặt ngay trên đó để hai khung không chồng nhau */
146	#wxScenario{position:fixed;left:50%;transform:translateX(-50%);bottom:calc(18px + env(safe-area-inset-bottom,0px));
147	  width:min(440px,calc(100vw - 32px));padding:12px 16px 13px;display:flex;flex-direction:column;gap:4px;}
148	#wxScenario .top{display:flex;justify-content:space-between;align-items:baseline;gap:12px;}
149	#wxScenario .step{font-family:var(--font-mono);font-size:10.5px;letter-spacing:.14em;color:var(--han);font-variant-numeric:tabular-nums;}
150	#wxScenario .exit{font-size:10.5px;color:var(--muted);}
151	#wxScenario h2{margin:0;font-family:var(--font-display);font-weight:600;font-size:20px;line-height:1.1;color:var(--gold);text-wrap:balance;}
152	#wxScenario p{margin:0;font-size:12.5px;line-height:1.5;color:var(--text);min-height:3em;}
153	#wxScenario .bar{height:2px;background:rgba(255,255,255,.08);border-radius:2px;overflow:hidden;margin-top:4px;}
154	#wxScenario .bar i{display:block;height:100%;width:0;background:var(--gold);}
155	body.touring #wxScenario{bottom:calc(190px + env(safe-area-inset-bottom,0px));}
156	body.wxrun .specs{display:none;}   /* như Tour: bảng Thông số nhường chỗ cho khung chú thích */
157	html:is([lang=th],[lang=hi],[lang=ar]) #wxScenario p{line-height:1.7;}
158	#loading{position:fixed;inset:0;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:10px;
159	  background:var(--ink);font-family:var(--font-display);font-size:26px;color:var(--gold);z-index:20;transition:opacity .6s;}
160	#loading small{font-family:var(--font-body);font-size:12px;color:var(--muted);}
161	#loading.done{opacity:0;pointer-events:none;}
162	/* Nhãn 3D trên mặt cắt Hầm sông Hàn */
163	#hrLabels{position:fixed;inset:0;pointer-events:none;z-index:5;overflow:hidden;}
164	.hr-label{position:absolute;left:0;top:0;padding:3px 7px;font:500 11px/1.2 var(--font-body);color:var(--text);background:rgba(10,18,30,.72);border:1px solid rgba(230,189,106,.55);border-radius:4px;white-space:nowrap;will-change:transform;}
165	.hr-label::after{content:"";position:absolute;left:50%;top:100%;width:1px;height:10px;background:rgba(230,189,106,.7);}
166	/* Hai khối bọc trong suốt nên bố cục .brand mở giữ như cũ; nút ⚙ / ☰ dùng ở cả máy tính lẫn điện thoại, nút × chỉ điện thoại */
167	.brand-head,#brandBody{display:contents;}
168	.sheet-close{display:none;}
169	#btnSettings[aria-expanded="true"],#btnViewsSheet[aria-expanded="true"]{background:rgba(230,189,106,.16);border-color:rgba(230,189,106,.55);color:var(--gold);}
170	/* ===== Máy tính: bảng thu gọn (D-025) =====
171	   Đóng: .brand chỉ còn nút ⚙, .views chỉ còn nút ☰ Góc nhìn, giữ neo 14 px ở hai góc trên (RTL tự đổi bên).
172	   Mở (body.sheet-settings / body.sheet-views, compactUI.ts): bảng như bố cục cũ, nút ở đầu bảng. */
173	body:not(.compact) #btnSettings{display:inline-flex;align-items:center;justify-content:center;flex:0 0 auto;width:36px;height:36px;padding:0;}
174	body:not(.compact) #btnSettings svg{width:16px;height:16px;}
175	body:not(.compact) #btnViewsSheet{display:inline-flex;align-items:center;gap:6px;padding:8px 12px;white-space:nowrap;}
176	body:not(.compact) #btnViewsSheet svg{width:14px;height:14px;flex:0 0 auto;}
177	body:not(.compact) .views .label{display:none;}   /* nút ☰ Góc nhìn đã là tiêu đề bảng */
178	body:not(.compact):not(.sheet-settings) .brand{padding:6px;}
179	body:not(.compact):not(.sheet-settings) .brand-top,body:not(.compact):not(.sheet-settings) .brand h1,body:not(.compact):not(.sheet-settings) #brandBody{display:none;}
180	body:not(.compact).sheet-settings .brand-head{display:flex;align-items:center;gap:10px;order:-1;}   /* mở: hàng đầu là ⚙ + tên, ⚙ giữ góc cũ */
181	body:not(.compact).sheet-settings #btnSettings{order:-1;}
182	body:not(.compact):not(.sheet-views) .views{width:auto;padding:6px;overflow:visible;}
183	body:not(.compact):not(.sheet-views) .views > :not(#btnViewsSheet){display:none;}
184	body:not(.compact).sheet-views #btnViewsSheet{order:-1;align-self:flex-start;}
185	/* ===== Chế độ gọn (điện thoại): body.compact do compactUI.ts đặt theo CONFIG.ui.compactQuery =====
186	   Đóng: thanh trên (tên + nút Cài đặt) và thanh dưới (chip cầu, Tour 4 cầu, nút Góc nhìn).
187	   Mở: body.sheet-settings → .brand thành tờ đáy; body.sheet-views → danh sách góc nhìn hiện trên thanh dưới. */
188	body.compact .panel{-webkit-tap-highlight-color:transparent;touch-action:manipulation;user-select:none;-webkit-user-select:none;}
189	body.compact .panel{backdrop-filter:none;-webkit-backdrop-filter:none;box-shadow:none;background:rgba(10,18,22,.92);}   /* bỏ blur: GPU khỏi làm mờ lại canvas dưới panel mỗi khung; nền đục bù lại */
190	body.compact #btnMusic[aria-pressed="true"] .eq rect{animation:none;}   /* animation vô hạn buộc dựng lại lớp mỗi khung */
191	body.compact .specs,body.compact .stats{display:none;}   /* màn nhỏ: không đủ chỗ cho bảng Thông số và FPS */
192	body.compact .panel button{min-height:40px;font-size:13px;}
193	body.compact .panel select{min-height:40px;font-size:13px;}
194	body.compact .donate{min-height:40px;}
195	body.compact #btnSettings,body.compact .sheet-close{align-items:center;justify-content:center;flex:0 0 auto;width:40px;height:40px;padding:0;}
196	body.compact #btnSettings svg,body.compact .sheet-close svg{width:18px;height:18px;}
197	/* Thanh trên: chỉ tên + nút Cài đặt, neo trên-trái */
198	body.compact .brand{top:calc(8px + env(safe-area-inset-top,0px));inset-inline-start:calc(8px + env(safe-area-inset-left,0px));
199	  max-width:calc(100vw - 16px);padding:6px;padding-inline-start:12px;gap:10px;}
200	body.compact .brand-head{display:flex;align-items:center;gap:10px;min-width:0;}
201	body.compact .brand h1{flex:1 1 auto;min-width:0;font-size:20px;line-height:1.15;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
202	body.compact #btnSettings{display:inline-flex;}
203	body.compact .eyebrow,body.compact .brand-top,body.compact #brandBody{display:none;}
204	/* Tờ Cài đặt: tờ đáy cuộn dọc, ô ngôn ngữ + toàn bộ điều khiển; thanh dưới ẩn trong lúc mở */
205	body.compact.sheet-settings .brand{top:auto;bottom:0;inset-inline:0;max-width:none;max-height:70dvh;overflow-y:auto;overscroll-behavior:contain;
206	  padding:12px calc(14px + env(safe-area-inset-right,0px)) calc(14px + env(safe-area-inset-bottom,0px)) calc(14px + env(safe-area-inset-left,0px));
207	  border-bottom:0;border-radius:14px 14px 0 0;}
208	body.compact.sheet-settings .brand-head{order:-1;}
209	body.compact.sheet-settings .brand .sheet-close{display:inline-flex;}
210	body.compact.sheet-settings .brand-top{display:flex;flex-wrap:wrap;}
211	body.compact.sheet-settings .eyebrow{display:block;}
212	body.compact.sheet-settings #brandBody{display:flex;flex-direction:column;gap:10px;}
213	body.compact.sheet-settings .views{display:none;}
214	/* Thanh dưới: toàn bề ngang, một hàng; hàng chip cầu cuộn ngang (chính .views không tràn ngang) */
215	body.compact .views{top:auto;bottom:0;inset-inline:0;width:auto;max-height:none;overflow:visible;
216	  flex-direction:row;flex-wrap:wrap;align-items:center;gap:6px;
217	  padding:8px calc(8px + env(safe-area-inset-right,0px)) calc(8px + env(safe-area-inset-bottom,0px)) calc(8px + env(safe-area-inset-left,0px));
218	  border-bottom:0;border-radius:14px 14px 0 0;}
219	body.compact .views .label{display:none;}
220	body.compact .seg{display:flex;flex:1 1 0;min-width:0;margin:0;overflow-x:auto;scroll-snap-type:x mandatory;overscroll-behavior-x:contain;scrollbar-width:none;}
221	body.compact .seg::-webkit-scrollbar{display:none;}
222	/* Vệt mờ báo hàng chip còn cuộn được (compactUI.ts bật .more-start / .more-end; theo hướng chữ: start = đầu dòng) */
223	body.compact .seg.more-end{-webkit-mask-image:linear-gradient(to right,#000 calc(100% - 28px),transparent);mask-image:linear-gradient(to right,#000 calc(100% - 28px),transparent);}
224	body.compact .seg.more-start{-webkit-mask-image:linear-gradient(to left,#000 calc(100% - 28px),transparent);mask-image:linear-gradient(to left,#000 calc(100% - 28px),transparent);}
225	body.compact .seg.more-start.more-end{-webkit-mask-image:linear-gradient(to right,transparent,#000 28px,#000 calc(100% - 28px),transparent);mask-image:linear-gradient(to right,transparent,#000 28px,#000 calc(100% - 28px),transparent);}
226	html[dir=rtl] body.compact .seg.more-end{-webkit-mask-image:linear-gradient(to left,#000 calc(100% - 28px),transparent);mask-image:linear-gradient(to left,#000 calc(100% - 28px),transparent);}
227	html[dir=rtl] body.compact .seg.more-start{-webkit-mask-image:linear-gradient(to right,#000 calc(100% - 28px),transparent);mask-image:linear-gradient(to right,#000 calc(100% - 28px),transparent);}
228	html[dir=rtl] body.compact .seg.more-start.more-end{-webkit-mask-image:linear-gradient(to right,transparent,#000 28px,#000 calc(100% - 28px),transparent);mask-image:linear-gradient(to right,transparent,#000 28px,#000 calc(100% - 28px),transparent);}
229	body.compact .seg button{flex:0 0 auto;min-height:36px;padding:6px 10px;font-size:13px;white-space:nowrap;overflow-wrap:normal;scroll-snap-align:start;}
230	body.compact .tour-all,body.compact #btnViewsSheet{flex:0 0 auto;margin:0;white-space:nowrap;}
231	body.compact #btnViewsSheet{display:inline-flex;align-items:center;gap:6px;}
232	body.compact #btnViewsSheet svg{width:16px;height:16px;flex:0 0 auto;}
233	body.compact .view-list{display:none;}
234	/* Tờ Góc nhìn: danh sách của cầu đang chọn thành lưới 2 cột, phía trên thanh dưới */
235	body.compact.sheet-views .views .label{display:block;order:-3;flex:1 1 auto;margin:0;}
236	body.compact.sheet-views .views .sheet-close{display:inline-flex;order:-2;margin-inline-start:auto;}
237	body.compact.sheet-views .view-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px;align-content:start;
238	  order:-1;flex:1 0 100%;min-width:0;max-height:55dvh;overflow-y:auto;overscroll-behavior:contain;}
239	body.compact.sheet-views .view-list .swing-box,body.compact.sheet-views .view-list .mini-select{grid-column:1 / -1;}
240	body.compact.sheet-views .view-list .toggle{margin-top:0;}
241	/* Khung chú thích Tour / Kịch bản bão: ngay trên thanh dưới (--bar-h do compactUI.ts ghi) */
242	body.compact #tourCaption,body.compact #wxScenario{bottom:calc(var(--bar-h,60px) + 8px);max-height:34dvh;overflow-y:auto;}
243	body.compact.touring #wxScenario{bottom:calc(var(--bar-h,60px) + 16px + 34dvh);}
244	body.compact #tourCaption h2{font-size:20px;}
245	body.compact.sheet-settings .brand,body.compact.sheet-views .views{z-index:10;}   /* tờ đang mở nằm trên chú thích Tour/bão (không z-index thì chú thích đứng sau trong DOM nên đè lên) */
246	/* Dòng hướng dẫn: dưới thanh trên; #swStormNote thấp hơn để không chồng #swRideHint (có thể hiện cùng lúc) */
247	body.compact #hint,body.compact #swRideHint{top:calc(64px + env(safe-area-inset-top,0px));max-width:calc(100vw - 24px);box-sizing:border-box;text-align:center;}
248	body.compact #swStormNote{top:calc(124px + env(safe-area-inset-top,0px));max-width:calc(100vw - 24px);box-sizing:border-box;}
249	/* ===== Tự khám phá ===== */
250	/* Màn chọn phương tiện: lớp phủ chặn chuột vào canvas, phủ cả các bảng; có ô chọn ngôn ngữ riêng (#exLang) */
251	.ex-chooser{position:fixed;inset:0;z-index:20;display:flex;align-items:center;justify-content:center;padding:16px;box-sizing:border-box;background:rgba(6,10,13,.72);}
252	.ex-lang{display:block;margin:0 0 12px;width:max-content;}
253	.ex-box{position:static;max-width:min(720px,100%);max-height:100%;overflow-y:auto;padding:22px 24px;box-sizing:border-box;}
254	.ex-box h2{margin:0 0 16px;font-family:var(--font-display);font-weight:600;font-size:26px;line-height:1.15;color:var(--gold);text-wrap:balance;}
255	.ex-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;}
256	.ex-card{display:flex;flex-direction:column;align-items:flex-start;gap:4px;min-height:84px;padding:12px 14px;text-align:start;}
257	.ex-card b{font-weight:600;font-size:14px;color:var(--text);}
258	.ex-card span,.ex-card i{font-style:normal;font-size:11.5px;line-height:1.4;color:var(--muted);}
259	.ex-card:disabled{opacity:.55;cursor:not-allowed;}
260	.ex-card:disabled .ex-note{color:var(--gold);}

