/* Bố cục: khung 3D toàn màn hình, các bảng điều khiển nổi kiểu "bảng đồng" ở bốn góc.
   Giao diện cố ý chỉ một tông tối để nổi trên cảnh 3D. */
:root{
  --ink:#0b1216;            /* nền trang */
  --panel:rgba(10,18,22,.78);
  --panel-line:rgba(226,186,104,.26);
  --gold:#e6bd6a;           /* vàng kim của thân rồng */
  --gold-deep:#a97a28;
  --text:#eef0ea;
  --muted:#9fb0ad;
  --han:#5aa89a;            /* xanh sông Hàn */
  --font-display:'Cormorant Garamond','Times New Roman',serif;
  --font-body:'Be Vietnam Pro',system-ui,-apple-system,'Segoe UI',sans-serif;
  --font-mono:'JetBrains Mono',ui-monospace,Menlo,Consolas,monospace;
  color-scheme:dark;
}
[hidden]{display:none!important;}
html,body{height:100%;margin:0;overflow:hidden;background:var(--ink);color:var(--text);font-family:var(--font-body);}
#scene{position:fixed;inset:0;width:100%;height:100%;height:100dvh;display:block;outline:none;touch-action:none;}
.panel{position:fixed;background:var(--panel);border:1px solid var(--panel-line);border-radius:6px;
  backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);box-shadow:0 10px 30px rgba(0,0,0,.35);}
.brand{top:calc(14px + env(safe-area-inset-top,0px));inset-inline-start:calc(14px + env(safe-area-inset-left,0px));
  padding:14px 16px 14px;max-width:min(360px,calc(100vw - 28px));display:flex;flex-direction:column;gap:10px;}
.eyebrow{font-family:var(--font-mono);font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--han);}
h1{margin:0;font-family:var(--font-display);font-weight:600;font-size:34px;line-height:1;color:var(--gold);letter-spacing:.01em;text-wrap:balance;}
h1 span{color:var(--text);font-weight:500;font-size:.62em;letter-spacing:.04em;}
h1 .h1-main{color:var(--gold);font-weight:600;font-size:1em;letter-spacing:inherit;}
.row{display:flex;flex-wrap:wrap;gap:6px;}
.weather-row{display:flex;flex-direction:column;gap:6px;}
.weather-row .mini-select{margin-top:0;}
.weather-row output,#weatherKVal{min-width:3.2em;text-align:end;font-family:var(--font-mono);}
.brand-top{display:flex;align-items:center;justify-content:space-between;gap:10px;}
.lang{position:relative;flex:0 0 auto;}
.lang select{appearance:none;-webkit-appearance:none;font:500 11.5px/1.2 var(--font-body);color:var(--text);
  background:rgba(255,255,255,.04);border:1px solid rgba(230,189,106,.32);border-radius:4px;
  padding-block:5px;padding-inline:8px 22px;cursor:pointer;max-width:132px;}
@media (hover:hover){.lang select:hover{background:rgba(230,189,106,.12);}}
.lang select:focus-visible{outline:2px solid var(--gold);outline-offset:2px;}
.lang select option{background:var(--ink);color:var(--text);}
.lang::after{content:"";position:absolute;inset-inline-end:8px;top:50%;width:6px;height:6px;margin-top:-5px;
  border-right:1.5px solid var(--gold);border-bottom:1.5px solid var(--gold);transform:rotate(45deg);pointer-events:none;}
/* Font và nhịp chữ theo từng hệ chữ viết */
html[lang=ko]{--font-display:'Noto Serif KR',serif;--font-body:'Noto Sans KR',system-ui,sans-serif;--font-mono:'JetBrains Mono','Noto Sans KR',monospace;}
html[lang=ja]{--font-display:'Noto Serif JP',serif;--font-body:'Noto Sans JP',system-ui,sans-serif;--font-mono:'JetBrains Mono','Noto Sans JP',monospace;}
html[lang=zh]{--font-display:'Noto Serif SC',serif;--font-body:'Noto Sans SC',system-ui,sans-serif;--font-mono:'JetBrains Mono','Noto Sans SC',monospace;}
html[lang=th]{--font-display:'Noto Serif Thai',serif;--font-body:'Noto Sans Thai',system-ui,sans-serif;--font-mono:'JetBrains Mono','Noto Sans Thai',monospace;}
html[lang=ar]{--font-display:'Noto Naskh Arabic',serif;--font-body:'Noto Sans Arabic',system-ui,sans-serif;--font-mono:'JetBrains Mono','Noto Sans Arabic',monospace;}
html[lang=hi]{--font-display:'Noto Serif Devanagari',serif;--font-body:'Noto Sans Devanagari',system-ui,sans-serif;--font-mono:'JetBrains Mono','Noto Sans Devanagari',monospace;}
html[lang=ru]{--font-display:'Noto Serif',serif;--font-body:'Noto Sans',system-ui,sans-serif;--font-mono:'JetBrains Mono','Noto Sans',monospace;}
html:is([lang=ko],[lang=ja],[lang=zh],[lang=th],[lang=ar],[lang=hi]) h1{font-size:27px;line-height:1.3;}
html:is([lang=ko],[lang=ja],[lang=zh],[lang=th],[lang=ar],[lang=hi]) #tourCaption h2{font-size:20px;line-height:1.35;}
html:is([lang=ko],[lang=ja],[lang=zh],[lang=th],[lang=ar],[lang=hi]) .specs dd{font-size:20px;}
html:is([lang=ko],[lang=ja],[lang=zh],[lang=th],[lang=ar],[lang=hi]) #loading{font-size:22px;}
html:is([lang=ko],[lang=ja],[lang=zh],[lang=th],[lang=ar],[lang=hi]) .eyebrow,
html:is([lang=ko],[lang=ja],[lang=zh],[lang=th],[lang=ar],[lang=hi]) .label,
html:is([lang=ko],[lang=ja],[lang=zh],[lang=th],[lang=ar],[lang=hi]) #tourCaption .step{letter-spacing:.04em;}
html[lang=ar] *{letter-spacing:0!important;}
html:is([lang=th],[lang=hi],[lang=ar]) #tourCaption p{line-height:1.7;}
button{font:500 12.5px/1.2 var(--font-body);color:var(--text);background:rgba(255,255,255,.04);
  border:1px solid rgba(230,189,106,.32);border-radius:4px;padding:8px 11px;cursor:pointer;
  transition:background .15s,border-color .15s,color .15s;}
@media (hover:hover){button:hover{background:rgba(230,189,106,.12);}}
button:focus-visible,input:focus-visible{outline:2px solid var(--gold);outline-offset:2px;}
button[aria-pressed="true"]{background:linear-gradient(180deg,var(--gold),var(--gold-deep));color:#1a1206;border-color:var(--gold);}
.slider{display:flex;align-items:center;gap:8px;font-size:11.5px;color:var(--muted);}
.slider input{flex:1;accent-color:var(--gold);min-width:0;}
.audio-row{display:flex;align-items:center;gap:10px;}
#btnMusic,#btnVoice{display:inline-flex;align-items:center;gap:7px;flex:0 0 auto;}
#btnVoice svg{width:14px;height:14px;flex:0 0 auto;}
#btnVoice:disabled{opacity:.35;cursor:default;}
#btnMusic svg{width:14px;height:14px;flex:0 0 auto;}
#btnMusic .eq{display:none;}
#btnMusic[aria-pressed="true"] .eq{display:inline;}
#btnMusic[aria-pressed="true"] .eq rect{animation:eq 1.1s ease-in-out infinite;transform-origin:50% 100%;transform-box:fill-box;}
#btnMusic[aria-pressed="true"] .eq rect:nth-child(2){animation-delay:-.35s;}
#btnMusic[aria-pressed="true"] .eq rect:nth-child(3){animation-delay:-.7s;}
#btnMusic[aria-pressed="true"] .note{display:none;}
@keyframes eq{0%,100%{transform:scaleY(.35);}50%{transform:scaleY(1);}}
.audio-row input{flex:1;min-width:0;accent-color:var(--gold);}
.audio-row input:disabled{opacity:.35;}
.views{top:calc(14px + env(safe-area-inset-top,0px));inset-inline-end:calc(14px + env(safe-area-inset-right,0px));
  padding:12px;display:flex;flex-direction:column;gap:6px;width:228px;}
.seg{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:3px;padding:3px;border:1px solid var(--panel-line);border-radius:5px;margin-bottom:2px;}
.seg button{min-width:0;padding:6px 4px;font-size:11px;line-height:1.2;text-align:center;background:transparent;border-color:transparent;color:var(--muted);overflow-wrap:anywhere;}
.mini-select{display:flex;flex-direction:column;gap:4px;margin-top:2px;font-size:10.5px;color:var(--muted);}
.donate{display:inline-flex;align-items:center;gap:6px;margin-top:6px;padding:6px 10px;border:1px solid rgba(230,189,106,.32);border-radius:4px;color:var(--gold);font:12px var(--font-body);text-decoration:none;}
.donate svg{width:14px;height:14px;flex:0 0 auto;}
.donate[hidden]{display:none;}
@media (hover:hover){.donate:hover{background:rgba(230,189,106,.1);}}
.swing-box{display:flex;flex-direction:column;gap:7px;padding:8px;border:1px dashed var(--panel-line);border-radius:5px;margin-top:2px;}
.swing-btn{background:linear-gradient(180deg,var(--gold),var(--gold-deep));color:#1a1206;border-color:var(--gold);font-weight:600;text-align:center!important;}
.swing-btn:disabled{opacity:.6;cursor:progress;}
.swing-state{font-size:11.5px;color:var(--muted);line-height:1.35;}
.swing-state b{color:var(--gold);font-weight:500;}
.swing-note{font-size:10px;color:var(--muted);line-height:1.4;}
.views{max-height:calc(100vh - 28px - 26px - env(safe-area-inset-top,0px) - env(safe-area-inset-bottom,0px));overflow-y:auto;}   /* 28 = hai lề 14 px; 26 = padding 12 px × 2 + viền 1 px × 2 (max-height tính phần nội dung) */
.mini-select select{appearance:auto;font:500 12px/1.2 var(--font-body);color:var(--text);background:rgba(255,255,255,.04);border:1px solid rgba(230,189,106,.32);border-radius:4px;padding:6px;}
.mini-select select option{background:var(--ink);color:var(--text);}
.seg button[aria-pressed="true"]{background:rgba(230,189,106,.16);border-color:rgba(230,189,106,.55);color:var(--gold);}
.view-list{display:flex;flex-direction:column;gap:6px;}
.tour-all{margin-bottom:6px;}
.view-list .toggle,.weather-row .toggle{display:flex;align-items:center;gap:8px;margin-top:2px;font-size:11.5px;color:var(--muted);background:transparent;}
.view-list .toggle::before,.weather-row .toggle::before{content:"";width:11px;height:11px;flex:0 0 auto;border:1.5px solid var(--gold);border-radius:2px;}
.view-list .toggle[aria-pressed="true"],.weather-row .toggle[aria-pressed="true"]{background:transparent;color:var(--text);border-color:rgba(230,189,106,.32);}
.view-list .toggle[aria-pressed="true"]::before,.weather-row .toggle[aria-pressed="true"]::before{background:var(--gold);box-shadow:inset 0 0 0 2px var(--ink);}
/* Thẻ "Ảnh hưởng tới cầu": mỗi công trình một ô (tên + trạng thái lưu thông, gió tại mặt cầu, hiệu ứng) */
.wx-impact{display:flex;flex-direction:column;gap:6px;max-height:max(120px,calc(100vh - 560px));overflow-y:auto;}   /* chừa chỗ cho bảng Thông số ở góc dưới */
.wx-item{display:flex;flex-direction:column;gap:2px;padding:6px 8px;border:1px solid rgba(230,189,106,.2);border-radius:4px;background:rgba(255,255,255,.03);font-size:11px;line-height:1.35;color:var(--muted);}
.wx-head{display:flex;justify-content:space-between;align-items:baseline;gap:8px;color:var(--text);font-weight:500;}
.wx-st{font:500 10px/1 var(--font-mono);padding:3px 6px;border-radius:3px;border:1px solid currentColor;white-space:nowrap;}
.wx-st.open{color:#7bd18b;}.wx-st.closed{color:#f07b6b;}
.wx-wind{font-variant-numeric:tabular-nums;color:var(--text);}
.wx-note{font-size:10px;color:var(--muted);line-height:1.4;}
.views .label,.specs .label{font-family:var(--font-mono);font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);margin-bottom:2px;}
.views button{text-align:start;}
.specs{inset-inline-start:calc(14px + env(safe-area-inset-left,0px));bottom:calc(14px + env(safe-area-inset-bottom,0px));padding:12px 16px;}
.specs dl{margin:0;display:grid;grid-template-columns:repeat(4,auto);gap:4px 22px;}
.specs dt{font-size:10.5px;color:var(--muted);}
.specs dd{margin:0;font-family:var(--font-display);font-size:22px;font-weight:600;color:var(--gold);font-variant-numeric:tabular-nums;}
.specs small{display:block;margin-top:6px;font-size:10.5px;color:var(--muted);max-width:44ch;line-height:1.4;}
.stats{inset-inline-end:calc(14px + env(safe-area-inset-right,0px));bottom:calc(14px + env(safe-area-inset-bottom,0px));
  padding:10px 14px;font-family:var(--font-mono);font-size:11.5px;line-height:1.6;color:var(--muted);min-width:180px;}
.stats b{color:var(--text);font-weight:500;font-variant-numeric:tabular-nums;}
.stats .show b{color:var(--gold);}
#hint,#swRideHint{position:fixed;left:50%;transform:translateX(-50%);top:calc(14px + env(safe-area-inset-top,0px));
  padding:8px 14px;font-size:12px;color:var(--text);}
#swStormNote{position:fixed;left:50%;transform:translateX(-50%);top:calc(58px + env(safe-area-inset-top,0px));
  max-width:min(440px,calc(100vw - 32px));padding:8px 14px;font-size:12px;line-height:1.45;color:var(--text);text-align:center;}
#tourCaption{position:fixed;left:50%;transform:translateX(-50%);bottom:calc(18px + env(safe-area-inset-bottom,0px));
  width:min(440px,calc(100vw - 32px));padding:12px 16px 13px;display:flex;flex-direction:column;gap:4px;transition:opacity .45s;}
#tourCaption.fade{opacity:0;}
body.touring .specs{display:none;}
@media (max-width:1100px){body.touring .stats{display:none;}}
#tourCaption .top{display:flex;justify-content:space-between;align-items:baseline;gap:12px;}
#tourCaption .step{font-family:var(--font-mono);font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--han);font-variant-numeric:tabular-nums;}
#tourCaption .exit{font-size:10.5px;color:var(--muted);}
/* Chữ hướng dẫn hai bản: chuột (mặc định) / cảm ứng (thiết bị không có hover) */
.hint-touch{display:none;}
@media (hover:none){.hint-mouse{display:none;}.hint-touch{display:inline;}[data-view="walk"],#hint{display:none!important;}}
#tourCaption h2{margin:0;font-family:var(--font-display);font-weight:600;font-size:24px;line-height:1.1;color:var(--gold);text-wrap:balance;}
#tourCaption p{margin:0;font-size:12.5px;line-height:1.5;color:var(--text);}
#tourCaption .bar{height:2px;background:rgba(255,255,255,.08);border-radius:2px;overflow:hidden;margin-top:4px;}
#tourCaption .bar i{display:block;height:100%;width:100%;transform:scaleX(0);transform-origin:left;background:var(--gold);}
[dir=rtl] #tourCaption .bar i{transform-origin:right;}
/* Khung chú thích Kịch bản bão: cùng kiểu #tourCaption, đặt ngay trên đó để hai khung không chồng nhau */
#wxScenario{position:fixed;left:50%;transform:translateX(-50%);bottom:calc(18px + env(safe-area-inset-bottom,0px));
  width:min(440px,calc(100vw - 32px));padding:12px 16px 13px;display:flex;flex-direction:column;gap:4px;}
#wxScenario .top{display:flex;justify-content:space-between;align-items:baseline;gap:12px;}
#wxScenario .step{font-family:var(--font-mono);font-size:10.5px;letter-spacing:.14em;color:var(--han);font-variant-numeric:tabular-nums;}
#wxScenario .exit{font-size:10.5px;color:var(--muted);}
#wxScenario h2{margin:0;font-family:var(--font-display);font-weight:600;font-size:20px;line-height:1.1;color:var(--gold);text-wrap:balance;}
#wxScenario p{margin:0;font-size:12.5px;line-height:1.5;color:var(--text);min-height:3em;}
#wxScenario .bar{height:2px;background:rgba(255,255,255,.08);border-radius:2px;overflow:hidden;margin-top:4px;}
#wxScenario .bar i{display:block;height:100%;width:0;background:var(--gold);}
body.touring #wxScenario{bottom:calc(190px + env(safe-area-inset-bottom,0px));}
body.wxrun .specs{display:none;}   /* như Tour: bảng Thông số nhường chỗ cho khung chú thích */
html:is([lang=th],[lang=hi],[lang=ar]) #wxScenario p{line-height:1.7;}
#loading{position:fixed;inset:0;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:10px;
  background:var(--ink);font-family:var(--font-display);font-size:26px;color:var(--gold);z-index:20;transition:opacity .6s;}
#loading small{font-family:var(--font-body);font-size:12px;color:var(--muted);}
#loading.done{opacity:0;pointer-events:none;}
/* Nhãn 3D trên mặt cắt Hầm sông Hàn */
#hrLabels{position:fixed;inset:0;pointer-events:none;z-index:5;overflow:hidden;}
.hr-label{position:absolute;left:0;top:0;padding:3px 7px;font:500 11px/1.2 var(--font-body);color:var(--text);background:rgba(10,18,30,.72);border:1px solid rgba(230,189,106,.55);border-radius:4px;white-space:nowrap;will-change:transform;}
.hr-label::after{content:"";position:absolute;left:50%;top:100%;width:1px;height:10px;background:rgba(230,189,106,.7);}
/* Hai khối bọc trong suốt nên bố cục .brand mở giữ như cũ; nút ⚙ / ☰ dùng ở cả máy tính lẫn điện thoại, nút × chỉ điện thoại */
.brand-head,#brandBody{display:contents;}
.sheet-close{display:none;}
#btnSettings[aria-expanded="true"],#btnViewsSheet[aria-expanded="true"]{background:rgba(230,189,106,.16);border-color:rgba(230,189,106,.55);color:var(--gold);}
/* ===== Máy tính: bảng thu gọn (D-025) =====
   Đóng: .brand chỉ còn nút ⚙, .views chỉ còn nút ☰ Góc nhìn, giữ neo 14 px ở hai góc trên (RTL tự đổi bên).
   Mở (body.sheet-settings / body.sheet-views, compactUI.ts): bảng như bố cục cũ, nút ở đầu bảng. */
body:not(.compact) #btnSettings{display:inline-flex;align-items:center;justify-content:center;flex:0 0 auto;width:36px;height:36px;padding:0;}
body:not(.compact) #btnSettings svg{width:16px;height:16px;}
body:not(.compact) #btnViewsSheet{display:inline-flex;align-items:center;gap:6px;padding:8px 12px;white-space:nowrap;}
body:not(.compact) #btnViewsSheet svg{width:14px;height:14px;flex:0 0 auto;}
body:not(.compact) .views .label{display:none;}   /* nút ☰ Góc nhìn đã là tiêu đề bảng */
body:not(.compact):not(.sheet-settings) .brand{padding:6px;}
body:not(.compact):not(.sheet-settings) .brand-top,body:not(.compact):not(.sheet-settings) .brand h1,body:not(.compact):not(.sheet-settings) #brandBody{display:none;}
body:not(.compact).sheet-settings .brand-head{display:flex;align-items:center;gap:10px;order:-1;}   /* mở: hàng đầu là ⚙ + tên, ⚙ giữ góc cũ */
body:not(.compact).sheet-settings #btnSettings{order:-1;}
body:not(.compact):not(.sheet-views) .views{width:auto;padding:6px;overflow:visible;}
body:not(.compact):not(.sheet-views) .views > :not(#btnViewsSheet){display:none;}
body:not(.compact).sheet-views #btnViewsSheet{order:-1;align-self:flex-start;}
/* ===== Chế độ gọn (điện thoại): body.compact do compactUI.ts đặt theo CONFIG.ui.compactQuery =====
   Đóng: thanh trên (tên + nút Cài đặt) và thanh dưới (chip cầu, Tour 4 cầu, nút Góc nhìn).
   Mở: body.sheet-settings → .brand thành tờ đáy; body.sheet-views → danh sách góc nhìn hiện trên thanh dưới. */
body.compact .panel{-webkit-tap-highlight-color:transparent;touch-action:manipulation;user-select:none;-webkit-user-select:none;}
body.compact .panel{backdrop-filter:none;-webkit-backdrop-filter:none;box-shadow:none;background:rgba(10,18,22,.92);}   /* bỏ blur: GPU khỏi làm mờ lại canvas dưới panel mỗi khung; nền đục bù lại */
body.compact #btnMusic[aria-pressed="true"] .eq rect{animation:none;}   /* animation vô hạn buộc dựng lại lớp mỗi khung */
body.compact .specs,body.compact .stats{display:none;}   /* màn nhỏ: không đủ chỗ cho bảng Thông số và FPS */
body.compact .panel button{min-height:40px;font-size:13px;}
body.compact .panel select{min-height:40px;font-size:13px;}
body.compact .donate{min-height:40px;}
body.compact #btnSettings,body.compact .sheet-close{align-items:center;justify-content:center;flex:0 0 auto;width:40px;height:40px;padding:0;}
body.compact #btnSettings svg,body.compact .sheet-close svg{width:18px;height:18px;}
/* Thanh trên: chỉ tên + nút Cài đặt, neo trên-trái */
body.compact .brand{top:calc(8px + env(safe-area-inset-top,0px));inset-inline-start:calc(8px + env(safe-area-inset-left,0px));
  max-width:calc(100vw - 16px);padding:6px;padding-inline-start:12px;gap:10px;}
body.compact .brand-head{display:flex;align-items:center;gap:10px;min-width:0;}
body.compact .brand h1{flex:1 1 auto;min-width:0;font-size:20px;line-height:1.15;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
body.compact #btnSettings{display:inline-flex;}
body.compact .eyebrow,body.compact .brand-top,body.compact #brandBody{display:none;}
/* Tờ Cài đặt: tờ đáy cuộn dọc, ô ngôn ngữ + toàn bộ điều khiển; thanh dưới ẩn trong lúc mở */
body.compact.sheet-settings .brand{top:auto;bottom:0;inset-inline:0;max-width:none;max-height:70dvh;overflow-y:auto;overscroll-behavior:contain;
  padding:12px calc(14px + env(safe-area-inset-right,0px)) calc(14px + env(safe-area-inset-bottom,0px)) calc(14px + env(safe-area-inset-left,0px));
  border-bottom:0;border-radius:14px 14px 0 0;}
body.compact.sheet-settings .brand-head{order:-1;}
body.compact.sheet-settings .brand .sheet-close{display:inline-flex;}
body.compact.sheet-settings .brand-top{display:flex;flex-wrap:wrap;}
body.compact.sheet-settings .eyebrow{display:block;}
body.compact.sheet-settings #brandBody{display:flex;flex-direction:column;gap:10px;}
body.compact.sheet-settings .views{display:none;}
/* Thanh dưới: toàn bề ngang, một hàng; hàng chip cầu cuộn ngang (chính .views không tràn ngang) */
body.compact .views{top:auto;bottom:0;inset-inline:0;width:auto;max-height:none;overflow:visible;
  flex-direction:row;flex-wrap:wrap;align-items:center;gap:6px;
  padding:8px calc(8px + env(safe-area-inset-right,0px)) calc(8px + env(safe-area-inset-bottom,0px)) calc(8px + env(safe-area-inset-left,0px));
  border-bottom:0;border-radius:14px 14px 0 0;}
body.compact .views .label{display:none;}
body.compact .seg{display:flex;flex:1 1 0;min-width:0;margin:0;overflow-x:auto;scroll-snap-type:x mandatory;overscroll-behavior-x:contain;scrollbar-width:none;}
body.compact .seg::-webkit-scrollbar{display:none;}
/* Vệt mờ báo hàng chip còn cuộn được (compactUI.ts bật .more-start / .more-end; theo hướng chữ: start = đầu dòng) */
body.compact .seg.more-end{-webkit-mask-image:linear-gradient(to right,#000 calc(100% - 28px),transparent);mask-image:linear-gradient(to right,#000 calc(100% - 28px),transparent);}
body.compact .seg.more-start{-webkit-mask-image:linear-gradient(to left,#000 calc(100% - 28px),transparent);mask-image:linear-gradient(to left,#000 calc(100% - 28px),transparent);}
body.compact .seg.more-start.more-end{-webkit-mask-image:linear-gradient(to right,transparent,#000 28px,#000 calc(100% - 28px),transparent);mask-image:linear-gradient(to right,transparent,#000 28px,#000 calc(100% - 28px),transparent);}
html[dir=rtl] body.compact .seg.more-end{-webkit-mask-image:linear-gradient(to left,#000 calc(100% - 28px),transparent);mask-image:linear-gradient(to left,#000 calc(100% - 28px),transparent);}
html[dir=rtl] body.compact .seg.more-start{-webkit-mask-image:linear-gradient(to right,#000 calc(100% - 28px),transparent);mask-image:linear-gradient(to right,#000 calc(100% - 28px),transparent);}
html[dir=rtl] body.compact .seg.more-start.more-end{-webkit-mask-image:linear-gradient(to right,transparent,#000 28px,#000 calc(100% - 28px),transparent);mask-image:linear-gradient(to right,transparent,#000 28px,#000 calc(100% - 28px),transparent);}
body.compact .seg button{flex:0 0 auto;min-height:36px;padding:6px 10px;font-size:13px;white-space:nowrap;overflow-wrap:normal;scroll-snap-align:start;}
body.compact .tour-all,body.compact #btnViewsSheet{flex:0 0 auto;margin:0;white-space:nowrap;}
body.compact #btnViewsSheet{display:inline-flex;align-items:center;gap:6px;}
body.compact #btnViewsSheet svg{width:16px;height:16px;flex:0 0 auto;}
body.compact .view-list{display:none;}
/* Tờ Góc nhìn: danh sách của cầu đang chọn thành lưới 2 cột, phía trên thanh dưới */
body.compact.sheet-views .views .label{display:block;order:-3;flex:1 1 auto;margin:0;}
body.compact.sheet-views .views .sheet-close{display:inline-flex;order:-2;margin-inline-start:auto;}
body.compact.sheet-views .view-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px;align-content:start;
  order:-1;flex:1 0 100%;min-width:0;max-height:55dvh;overflow-y:auto;overscroll-behavior:contain;}
body.compact.sheet-views .view-list .swing-box,body.compact.sheet-views .view-list .mini-select{grid-column:1 / -1;}
body.compact.sheet-views .view-list .toggle{margin-top:0;}
/* Khung chú thích Tour / Kịch bản bão: ngay trên thanh dưới (--bar-h do compactUI.ts ghi) */
body.compact #tourCaption,body.compact #wxScenario{bottom:calc(var(--bar-h,60px) + 8px);max-height:34dvh;overflow-y:auto;}
body.compact.touring #wxScenario{bottom:calc(var(--bar-h,60px) + 16px + 34dvh);}
body.compact #tourCaption h2{font-size:20px;}
body.compact.sheet-settings .brand,body.compact.sheet-views .views{z-index:10;}   /* tờ đang mở nằm trên chú thích Tour/bão (không z-index thì chú thích đứng sau trong DOM nên đè lên) */
/* Dòng hướng dẫn: dưới thanh trên; #swStormNote thấp hơn để không chồng #swRideHint (có thể hiện cùng lúc) */
body.compact #hint,body.compact #swRideHint{top:calc(64px + env(safe-area-inset-top,0px));max-width:calc(100vw - 24px);box-sizing:border-box;text-align:center;}
body.compact #swStormNote{top:calc(124px + env(safe-area-inset-top,0px));max-width:calc(100vw - 24px);box-sizing:border-box;}
/* ===== Tự khám phá ===== */
/* Màn chọn phương tiện: lớp phủ chặn chuột vào canvas, phủ cả các bảng; có ô chọn ngôn ngữ riêng (#exLang) */
.ex-chooser{position:fixed;inset:0;z-index:20;display:flex;align-items:center;justify-content:center;padding:16px;box-sizing:border-box;background:rgba(6,10,13,.72);}
.ex-lang{display:block;margin:0 0 12px;width:max-content;}
.ex-box{position:static;max-width:min(720px,100%);max-height:100%;overflow-y:auto;padding:22px 24px;box-sizing:border-box;}
.ex-box h2{margin:0 0 16px;font-family:var(--font-display);font-weight:600;font-size:26px;line-height:1.15;color:var(--gold);text-wrap:balance;}
.ex-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;}
.ex-card{display:flex;flex-direction:column;align-items:flex-start;gap:4px;min-height:84px;padding:12px 14px;text-align:start;}
.ex-card b{font-weight:600;font-size:14px;color:var(--text);}
