          <div><dt><svg class="env-ico" viewBox="0 0 24 24"><path d="M3 9h10.5a2.5 2.5 0 1 0-2.5-2.5M3 13h15a2.5 2.5 0 1 1-2.5 2.5M3 17h6"/></svg>Gió</dt><dd class="v" data-wind></dd></div>
